// Phase 9 — shipping carriers. A company adds carrier accounts: "manual" (its own courier or a local company: the
// label is generated by Paxve, the status is moved by hand or by the driver), Aramex and DHL Express (switched off
// until the account's credentials are entered; then rate quotes, the carrier's label and tracking come from their
// API). A shipment belongs to an online order, a sales order or a delivery-board stop.

type shipReq struct {
	Number    int64
	Recipient string
	Phone     string
	Address   string
	City      string
	Country   string
	WeightKg  decimal.Decimal
	Pieces    int
	Contents  string
	Currency  string
	COD       decimal.Decimal
	Service   string
	Company   string
}

type rateOption struct {
	Carrier  string `json:"carrier"`
	Account  string `json:"account_id"`
	Name     string `json:"name"`
	Service  string `json:"service"`
	Amount   string `json:"amount"`
	Currency string `json:"currency"`
	Days     string `json:"days,omitempty"`
}

type shipEvent struct {
	At       string `json:"at"`
	Status   string `json:"status"`
	Text     string `json:"text"`
	Location string `json:"location,omitempty"`
}

type carrierDriver interface {
	Quote(ctx context.Context, cfg map[string]any, s shipReq) ([]rateOption, error)
	Create(ctx context.Context, cfg map[string]any, s shipReq) (tracking string, label []byte, err error)
	Track(ctx context.Context, cfg map[string]any, tracking string) (status string, events []shipEvent, err error)
}

// carrierBase lets tests point a driver at a fake server.
var carrierBase = map[string]string{}

var carrierHTTP = &http.Client{Timeout: 25 * time.Second}

func carrierFor(kind string) carrierDriver {
	switch kind {
	case "manual":
		return manualCarrier{}
	case "dhl":
		return dhlCarrier{}
	case "aramex":
		return aramexCarrier{}
	}
	return nil
}

func cfgNum(cfg map[string]any, k string) decimal.Decimal {
	switch v := cfg[k].(type) {
	case string:
		d, _ := decimal.NewFromString(strings.TrimSpace(v))
		return d
	case float64:
		return decimal.NewFromFloat(v)
	}
	return decimal.Zero
}

// ---------- manual / local courier ----------

type manualCarrier struct{}

func (manualCarrier) Quote(_ context.Context, cfg map[string]any, s shipReq) ([]rateOption, error) {
	flat, perKg := cfgNum(cfg, "flat_rate"), cfgNum(cfg, "per_kg")
	amt := flat.Add(perKg.Mul(s.WeightKg)).Round(2)
	cur := cfgString(cfg, "currency")
	if cur == "" {
		cur = s.Currency
	}
	return []rateOption{{Service: "standard", Amount: amt.String(), Currency: cur, Days: cfgString(cfg, "days")}}, nil
}

func (manualCarrier) Create(_ context.Context, cfg map[string]any, s shipReq) (string, []byte, error) {
	prefix := strings.ToUpper(strings.TrimSpace(cfgString(cfg, "prefix")))
	if prefix == "" || len(prefix) > 6 {
		prefix = "PX"
	}
	tracking := fmt.Sprintf("%s%06d%s", prefix, s.Number, randDigits(3))
	return tracking, shippingLabel(cfg, s, tracking, "Local courier"), nil
}

func (manualCarrier) Track(_ context.Context, _ map[string]any, _ string) (string, []shipEvent, error) {
	return "", nil, nil // moved by hand / by the driver
}

// shippingLabel: an A6-like label on an A4 page (sender, recipient, tracking number, cash to collect).
func shippingLabel(cfg map[string]any, s shipReq, tracking, carrier string) []byte {
	p := newPDF()
	p.newPage()
	p.line(carrier+" · "+s.Company, 11, true, 0)
	p.rule()
	p.line("TRACKING", 9, false, 0)
	p.line(tracking, 26, true, 0)
	p.gap(8)
	p.line("FROM", 9, false, 0)
	p.line(strings.TrimSpace(s.Company+" "+cfgString(cfg, "from_phone")), 12, true, 0)
	p.line(strings.TrimSpace(cfgString(cfg, "from_address")+" "+cfgString(cfg, "from_city")), 11, false, 0)
	p.gap(8)
	p.line("TO", 9, false, 0)
	p.line(s.Recipient, 16, true, 0)
	p.line(s.Phone, 13, true, 0)
	p.line(strings.TrimSpace(s.Address+" "+s.City+" "+s.Country), 12, false, 0)
	p.gap(8)
	p.rule()
	p.line(fmt.Sprintf("Shipment #%d · %s kg · %d piece(s)", s.Number, s.WeightKg.String(), s.Pieces), 11, false, 0)
	if s.Contents != "" {
		p.line("Contents: "+s.Contents, 10, false, 0)
	}
	if s.COD.IsPositive() {
		p.gap(6)
		p.line("CASH ON DELIVERY: "+s.COD.StringFixed(2)+" "+s.Currency, 18, true, 0)
	}
	return p.bytes()
}

// ---------- DHL Express (MyDHL API) ----------

type dhlCarrier struct{}

func dhlURL(cfg map[string]any, path string) string {
	if b := carrierBase["dhl"]; b != "" {
		return b + path
	}
	if cfgString(cfg, "sandbox") == "true" || cfg["sandbox"] == true {
		return "https://express.api.dhl.com/mydhlapi/test" + path
	}
	return "https://express.api.dhl.com/mydhlapi" + path
}

func carrierDo(ctx context.Context, req *http.Request) ([]byte, int, error) {
	req = req.WithContext(ctx)
	res, err := carrierHTTP.Do(req)
	if err != nil {
		return nil, 0, fmt.Errorf("carrier unreachable: %w", err)
	}
	defer res.Body.Close()
	b, err := io.ReadAll(io.LimitReader(res.Body, 8<<20))
	return b, res.StatusCode, err
}

func dhlReq(ctx context.Context, cfg map[string]any, method, path string, body any) ([]byte, error) {
	key, secret := cfgString(cfg, "api_key"), cfgString(cfg, "secret")
	if key == "" || secret == "" || cfgString(cfg, "account_number") == "" {
		return nil, &apiError{status: http.StatusUnprocessableEntity, code: "carrier_not_configured"}
	}
	var rd io.Reader
	if body != nil {
		b, _ := json.Marshal(body)
		rd = bytes.NewReader(b)
	}
	req, err := http.NewRequest(method, dhlURL(cfg, path), rd)
	if err != nil {
		return nil, err
	}
	req.SetBasicAuth(key, secret)
	req.Header.Set("Accept", "application/json")
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	b, code, err := carrierDo(ctx, req)
	if err != nil {
		return nil, &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: err.Error()}
	}
	if code >= 300 {
		var e struct {
			Detail string `json:"detail"`
			Title  string `json:"title"`
		}
		_ = json.Unmarshal(b, &e)
		return nil, &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: strings.TrimSpace(fmt.Sprintf("DHL %d %s %s", code, e.Title, e.Detail))}
	}
	return b, nil
}

func dhlParty(name, company, phone, address, city, country string) map[string]any {
	return map[string]any{
		"postalAddress":      map[string]any{"addressLine1": firstNonEmpty(address, city), "cityName": city, "countryCode": country},
		"contactInformation": map[string]any{"fullName": name, "companyName": firstNonEmpty(company, name), "phone": firstNonEmpty(phone, "0")},
	}
}

func (dhlCarrier) Quote(ctx context.Context, cfg map[string]any, s shipReq) ([]rateOption, error) {
	q := url.Values{}
	q.Set("accountNumber", cfgString(cfg, "account_number"))
	q.Set("originCountryCode", firstNonEmpty(cfgString(cfg, "from_country"), "LB"))
	q.Set("originCityName", cfgString(cfg, "from_city"))
	q.Set("destinationCountryCode", s.Country)
	q.Set("destinationCityName", s.City)
	q.Set("weight", s.WeightKg.String())
	q.Set("length", "10")
	q.Set("width", "10")
	q.Set("height", "10")
	q.Set("plannedShippingDate", time.Now().AddDate(0, 0, 1).Format(time.DateOnly))
	q.Set("isCustomsDeclarable", strconv.FormatBool(s.Country != firstNonEmpty(cfgString(cfg, "from_country"), "LB")))
	q.Set("unitOfMeasurement", "metric")
	b, err := dhlReq(ctx, cfg, http.MethodGet, "/rates?"+q.Encode(), nil)
	if err != nil {
		return nil, err
	}
	var res struct {
		Products []struct {
			Name       string `json:"productName"`
			Code       string `json:"productCode"`
			TotalPrice []struct {
				Price    float64 `json:"price"`
				Currency string  `json:"priceCurrency"`
			} `json:"totalPrice"`
			Delivery struct {
				Days int `json:"totalTransitDays"`
			} `json:"deliveryCapabilities"`
		} `json:"products"`
	}
	if err := json.Unmarshal(b, &res); err != nil {
		return nil, &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: "DHL: unreadable answer"}
	}
	var out []rateOption
	for _, p := range res.Products {
		if len(p.TotalPrice) == 0 {
			continue
		}
		tp := p.TotalPrice[0]
		days := ""
		if p.Delivery.Days > 0 {
			days = strconv.Itoa(p.Delivery.Days)
		}
		out = append(out, rateOption{Service: p.Code, Name: p.Name, Amount: decimal.NewFromFloat(tp.Price).StringFixed(2), Currency: tp.Currency, Days: days})
	}
	return out, nil
}

func (dhlCarrier) Create(ctx context.Context, cfg map[string]any, s shipReq) (string, []byte, error) {
	from := firstNonEmpty(cfgString(cfg, "from_country"), "LB")
	product := s.Service
	if product == "" {
		product = map[bool]string{true: "N", false: "P"}[s.Country == from]
	}
	body := map[string]any{
		"plannedShippingDateAndTime": time.Now().Add(2 * time.Hour).Format("2006-01-02T15:04:05 GMT-07:00"),
		"pickup":                     map[string]any{"isRequested": false},
		"productCode":                product,
		"accounts":                   []any{map[string]any{"typeCode": "shipper", "number": cfgString(cfg, "account_number")}},
		"customerDetails": map[string]any{
			"shipperDetails":  dhlParty(s.Company, s.Company, cfgString(cfg, "from_phone"), cfgString(cfg, "from_address"), cfgString(cfg, "from_city"), from),
			"receiverDetails": dhlParty(s.Recipient, "", s.Phone, s.Address, s.City, s.Country),
		},
		"content": map[string]any{
			"packages":              []any{map[string]any{"weight": s.WeightKg.InexactFloat64(), "dimensions": map[string]any{"length": 10, "width": 10, "height": 10}}},
			"isCustomsDeclarable":   s.Country != from,
			"description":           firstNonEmpty(s.Contents, "Goods"),
			"unitOfMeasurement":     "metric",
			"incoterm":              "DAP",
			"declaredValue":         s.COD.InexactFloat64(),
			"declaredValueCurrency": s.Currency,
		},
		"outputImageProperties": map[string]any{"imageOptions": []any{map[string]any{"typeCode": "label", "templateName": "ECOM26_84_001"}}},
		"customerReferences":    []any{map[string]any{"value": fmt.Sprintf("PX-%d", s.Number), "typeCode": "CU"}},
	}
	b, err := dhlReq(ctx, cfg, http.MethodPost, "/shipments", body)
	if err != nil {
		return "", nil, err
	}
	var res struct {
		Tracking  string `json:"shipmentTrackingNumber"`
		Documents []struct {
			Format  string `json:"imageFormat"`
			Content string `json:"content"`
		} `json:"documents"`
	}
	if err := json.Unmarshal(b, &res); err != nil || res.Tracking == "" {
		return "", nil, &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: "DHL: no tracking number"}
	}
	var label []byte
	for _, d := range res.Documents {
		if v, err := base64.StdEncoding.DecodeString(d.Content); err == nil && len(v) > 0 {
			label = v
			break
		}
	}
	return res.Tracking, label, nil
}

func (dhlCarrier) Track(ctx context.Context, cfg map[string]any, tracking string) (string, []shipEvent, error) {
	b, err := dhlReq(ctx, cfg, http.MethodGet, "/shipments/"+url.PathEscape(tracking)+"/tracking", nil)
	if err != nil {
		return "", nil, err
	}
	var res struct {
		Shipments []struct {
			Status string `json:"status"`
			Events []struct {
				Date     string `json:"date"`
				Time     string `json:"time"`
				Code     string `json:"typeCode"`
				Desc     string `json:"description"`
				Location struct {
					Address struct {
						City string `json:"addressLocality"`
					} `json:"address"`
				} `json:"serviceArea"`
			} `json:"events"`
		} `json:"shipments"`
	}
	if err := json.Unmarshal(b, &res); err != nil || len(res.Shipments) == 0 {
		return "", nil, &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: "DHL: unknown shipment"}
	}
	sh := res.Shipments[0]
	var ev []shipEvent
	status := "in_transit"
	for _, e := range sh.Events {
		ev = append(ev, shipEvent{At: strings.TrimSpace(e.Date + " " + e.Time), Status: e.Code, Text: e.Desc, Location: e.Location.Address.City})
		if e.Code == "OK" || strings.Contains(strings.ToLower(e.Desc), "delivered") {
			status = "delivered"
		}
	}
	if strings.EqualFold(sh.Status, "delivered") {
		status = "delivered"
	}
	return status, ev, nil
}

// ---------- Aramex (Shipping API v2, JSON) ----------

type aramexCarrier struct{}

func aramexURL(cfg map[string]any, path string) string {
	if b := carrierBase["aramex"]; b != "" {
		return b + path
	}
	if cfgString(cfg, "sandbox") == "true" || cfg["sandbox"] == true {
		return "https://ws.dev.aramex.net/ShippingAPI.V2" + path
	}
	return "https://ws.aramex.net/ShippingAPI.V2" + path
}

func aramexClient(cfg map[string]any) map[string]any {
	return map[string]any{"UserName": cfgString(cfg, "username"), "Password": cfgString(cfg, "password"), "Version": "v1.0",
		"AccountNumber": cfgString(cfg, "account_number"), "AccountPin": cfgString(cfg, "account_pin"), "AccountEntity": cfgString(cfg, "account_entity"),
		"AccountCountryCode": firstNonEmpty(cfgString(cfg, "from_country"), "LB"), "Source": 24}
}

type aramexNote struct {
	Code    string `json:"Code"`
	Message string `json:"Message"`
}

func aramexReq(ctx context.Context, cfg map[string]any, path string, body map[string]any, out any) error {
	if cfgString(cfg, "username") == "" || cfgString(cfg, "password") == "" || cfgString(cfg, "account_number") == "" {
		return &apiError{status: http.StatusUnprocessableEntity, code: "carrier_not_configured"}
	}
	body["ClientInfo"] = aramexClient(cfg)
	b, _ := json.Marshal(body)
	req, err := http.NewRequest(http.MethodPost, aramexURL(cfg, path), bytes.NewReader(b))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")
	res, code, err := carrierDo(ctx, req)
	if err != nil {
		return &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: err.Error()}
	}
	var head struct {
		HasErrors     bool         `json:"HasErrors"`
		Notifications []aramexNote `json:"Notifications"`
	}
	_ = json.Unmarshal(res, &head)
	if code >= 300 || head.HasErrors {
		msg := fmt.Sprintf("Aramex %d", code)
		for _, n := range head.Notifications {
			msg += " " + n.Code + " " + n.Message
		}
		return &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: strings.TrimSpace(msg)}
	}
	if err := json.Unmarshal(res, out); err != nil {
		return &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: "Aramex: unreadable answer"}
	}
	return nil
}

func aramexProduct(cfg map[string]any, country string) (group, typ string) {
	if country == firstNonEmpty(cfgString(cfg, "from_country"), "LB") {
		return "DOM", firstNonEmpty(cfgString(cfg, "domestic_product"), "OND")
	}
	return "EXP", firstNonEmpty(cfgString(cfg, "express_product"), "PPX")
}

func (aramexCarrier) Quote(ctx context.Context, cfg map[string]any, s shipReq) ([]rateOption, error) {
	g, t := aramexProduct(cfg, s.Country)
	w := map[string]any{"Unit": "KG", "Value": s.WeightKg.InexactFloat64()}
	var res struct {
		Total struct {
			Value    float64 `json:"Value"`
			Currency string  `json:"CurrencyCode"`
		} `json:"TotalAmount"`
	}
	err := aramexReq(ctx, cfg, "/RateCalculator/Service_1_0.svc/json/CalculateRate", map[string]any{
		"OriginAddress":      map[string]any{"City": cfgString(cfg, "from_city"), "CountryCode": firstNonEmpty(cfgString(cfg, "from_country"), "LB")},
		"DestinationAddress": map[string]any{"City": s.City, "CountryCode": s.Country},
		"ShipmentDetails": map[string]any{"PaymentType": "P", "ProductGroup": g, "ProductType": t, "ActualWeight": w, "ChargeableWeight": w,
			"NumberOfPieces": s.Pieces},
	}, &res)
	if err != nil {
		return nil, err
	}
	return []rateOption{{Service: t, Name: g + " " + t, Amount: decimal.NewFromFloat(res.Total.Value).StringFixed(2), Currency: res.Total.Currency}}, nil
}

func aramexParty(cfg map[string]any, own bool, name, phone, address, city, country string) map[string]any {
	p := map[string]any{
		"PartyAddress": map[string]any{"Line1": firstNonEmpty(address, city), "City": city, "CountryCode": country},
		"Contact":      map[string]any{"PersonName": name, "CompanyName": name, "PhoneNumber1": firstNonEmpty(phone, "0"), "CellPhone": firstNonEmpty(phone, "0")},
	}
	if own {
		p["AccountNumber"] = cfgString(cfg, "account_number")
	}
	return p
}

func (aramexCarrier) Create(ctx context.Context, cfg map[string]any, s shipReq) (string, []byte, error) {
	g, t := aramexProduct(cfg, s.Country)
	from := firstNonEmpty(cfgString(cfg, "from_country"), "LB")
	details := map[string]any{"ActualWeight": map[string]any{"Unit": "KG", "Value": s.WeightKg.InexactFloat64()}, "NumberOfPieces": s.Pieces,
		"ProductGroup": g, "ProductType": t, "PaymentType": "P", "DescriptionOfGoods": firstNonEmpty(s.Contents, "Goods"), "GoodsOriginCountry": from}
	if s.COD.IsPositive() {
		details["Services"] = "CODS"
		details["CashOnDeliveryAmount"] = map[string]any{"Value": s.COD.InexactFloat64(), "CurrencyCode": s.Currency}
	}
	var res struct {
		Shipments []struct {
			ID    string `json:"ID"`
			Label struct {
				Contents json.RawMessage `json:"LabelFileContents"`
			} `json:"ShipmentLabel"`
		} `json:"Shipments"`
	}
	err := aramexReq(ctx, cfg, "/Shipping/Service_1_0.svc/json/CreateShipments", map[string]any{
		"LabelInfo": map[string]any{"ReportID": 9201, "ReportType": "RPT"},
		"Shipments": []any{map[string]any{
			"Reference1":       fmt.Sprintf("PX-%d", s.Number),
			"Shipper":          aramexParty(cfg, true, s.Company, cfgString(cfg, "from_phone"), cfgString(cfg, "from_address"), cfgString(cfg, "from_city"), from),
			"Consignee":        aramexParty(cfg, false, s.Recipient, s.Phone, s.Address, s.City, s.Country),
			"ShippingDateTime": fmt.Sprintf("/Date(%d)/", time.Now().UnixMilli()),
			"DueDate":          fmt.Sprintf("/Date(%d)/", time.Now().Add(72*time.Hour).UnixMilli()),
			"Details":          details,
		}},
	}, &res)
	if err != nil {
		return "", nil, err
	}
	if len(res.Shipments) == 0 || res.Shipments[0].ID == "" {
		return "", nil, &apiError{status: http.StatusBadGateway, code: "carrier_error", detail: "Aramex: no tracking number"}
	}
	var label []byte
	raw := res.Shipments[0].Label.Contents
	var s64 string
	var ints []int
	if json.Unmarshal(raw, &s64) == nil && s64 != "" {
		label, _ = base64.StdEncoding.DecodeString(s64)
	} else if json.Unmarshal(raw, &ints) == nil && len(ints) > 0 {
		label = make([]byte, len(ints))
		for i, v := range ints {
			label[i] = byte(v)
		}
	}
	return res.Shipments[0].ID, label, nil
}

func (aramexCarrier) Track(ctx context.Context, cfg map[string]any, tracking string) (string, []shipEvent, error) {
	var res struct {
		Results []struct {
			Key   string `json:"Key"`
			Value []struct {
				Code     string `json:"UpdateCode"`
				Desc     string `json:"UpdateDescription"`
				At       string `json:"UpdateDateTime"`
				Location string `json:"UpdateLocation"`
			} `json:"Value"`
		} `json:"TrackingResults"`
	}
	if err := aramexReq(ctx, cfg, "/Tracking/Service_1_0.svc/json/TrackShipments", map[string]any{"Shipments": []string{tracking},
		"GetLastTrackingUpdateOnly": false}, &res); err != nil {
		return "", nil, err
	}
	status := "in_transit"
	var ev []shipEvent
	for _, r := range res.Results {
		for _, v := range r.Value {
			ev = append(ev, shipEvent{At: v.At, Status: v.Code, Text: v.Desc, Location: v.Location})
			if v.Code == "SH005" || v.Code == "SH006" || strings.Contains(strings.ToLower(v.Desc), "delivered") {
				status = "delivered"
			}
		}
	}
	return status, ev, nil
}

// ======================= API =======================

func carrierRow(ctx context.Context, tx pgx.Tx, cid, id string) (kind, name string, cfg map[string]any, err error) {
	var raw []byte
	var active bool
	err = tx.QueryRow(ctx, `SELECT carrier, name, config, is_active FROM carrier_accounts WHERE id = $1 AND company_id = $2`, id, cid).Scan(&kind, &name, &raw, &active)
	if errors.Is(err, pgx.ErrNoRows) {
		return "", "", nil, badRequest("invalid_carrier")
	}
	if err != nil {
		return
	}
	if !active {
		return "", "", nil, badRequest("carrier_inactive")
	}
	cfg = map[string]any{}
	_ = json.Unmarshal(raw, &cfg)
	cfg = openConfig(cfg)
	return
}

// configured: the account has what its carrier needs (manual always works).
func carrierConfigured(kind string, cfg map[string]any) bool {
	switch kind {
	case "dhl":
		return cfgString(cfg, "api_key") != "" && cfgString(cfg, "secret") != "" && cfgString(cfg, "account_number") != ""
	case "aramex":
		return cfgString(cfg, "username") != "" && cfgString(cfg, "password") != "" && cfgString(cfg, "account_number") != ""
	}
	return true
}

func (s *Server) listCarriers(w http.ResponseWriter, r *http.Request) {
	s.run(w, r, http.StatusOK, func(ctx context.Context, tx pgx.Tx) (any, error) {
		rows, err := tx.Query(ctx, `SELECT id::text, carrier, name, config, is_active, is_default, created_at FROM carrier_accounts WHERE company_id = $1
			ORDER BY is_default DESC, name`, r.PathValue("cid"))
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		out := []map[string]any{}
		for rows.Next() {
			var id, kind, name string
			var raw []byte
			var active, def bool
			var at time.Time
			if err := rows.Scan(&id, &kind, &name, &raw, &active, &def, &at); err != nil {
				return nil, err
			}
			cfg := map[string]any{}
			_ = json.Unmarshal(raw, &cfg)
			out = append(out, map[string]any{"id": id, "carrier": kind, "name": name, "config": maskConfig(cfg), "is_active": active, "is_default": def,
				"configured": carrierConfigured(kind, openConfig(cfg)), "created_at": at})
		}
		return out, rows.Err()
	})
}

var carrierCfgKeys = map[string]bool{"flat_rate": true, "per_kg": true, "currency": true, "days": true, "prefix": true, "from_address": true,
	"from_city": true, "from_country": true, "from_phone": true, "api_key": true, "secret": true, "account_number": true, "username": true,
	"password": true, "account_pin": true, "account_entity": true, "sandbox": true, "domestic_product": true, "express_product": true}

func (s *Server) saveCarrier(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Carrier   *string        `json:"carrier"`
		Name      *string        `json:"name"`
		Config    map[string]any `json:"config"`
		IsActive  *bool          `json:"is_active"`
		IsDefault *bool          `json:"is_default"`
	}
	if !decodeBody(w, r, &in) {
		return
	}
	cid, id := r.PathValue("cid"), r.PathValue("id")
	if id != "" && !isUUID(id) {
		writeErr(w, http.StatusNotFound, "not_found")
		return
	}
	if (in.Carrier != nil && !contains([]string{"manual", "aramex", "dhl"}, *in.Carrier)) || len(deref(in.Name)) > 80 || len(in.Config) > 30 {
		writeErr(w, http.StatusBadRequest, "bad_request")
		return
	}
	for k, v := range in.Config {
		sv, isStr := v.(string)
		_, isBool := v.(bool)
		_, isNum := v.(float64)
		if !carrierCfgKeys[k] || (!isStr && !isBool && !isNum) || len(sv) > 200 {
			writeErr(w, http.StatusBadRequest, "bad_config")
			return
		}
	}
	status := http.StatusOK
	if id == "" {
		status = http.StatusCreated
		if in.Carrier == nil || strings.TrimSpace(deref(in.Name)) == "" {
			writeErr(w, http.StatusBadRequest, "bad_request")
			return
		}
	}
	s.run(w, r, status, func(ctx context.Context, tx pgx.Tx) (any, error) {
		old := map[string]any{}
		if id != "" {
			var raw []byte
			if err := tx.QueryRow(ctx, `SELECT config FROM carrier_accounts WHERE id = $1 AND company_id = $2 FOR UPDATE`, id, cid).Scan(&raw); err != nil {
				if errors.Is(err, pgx.ErrNoRows) {
					return nil, notFound()
				}
				return nil, err
			}
			_ = json.Unmarshal(raw, &old)
		}
		cfg := old
		if in.Config != nil {
			cfg = mergeConfig(old, in.Config)
		}
		sealed, err := sealConfig(cfg)
		if err != nil {
			return nil, err
		}
		cb, _ := json.Marshal(sealed)
		if deref(boolStr(in.IsDefault)) == "true" {
			if _, err := tx.Exec(ctx, `UPDATE carrier_accounts SET is_default = false WHERE company_id = $1`, cid); err != nil {
				return nil, err
			}
		}
		if id == "" {
			if err := tx.QueryRow(ctx, `INSERT INTO carrier_accounts (company_id, carrier, name, config, is_active, is_default)
				VALUES ($1, $2, trim($3), $4, coalesce($5, true), coalesce($6, false)) RETURNING id::text`,
				cid, *in.Carrier, deref(in.Name), cb, in.IsActive, in.IsDefault).Scan(&id); err != nil {
				return nil, err
			}
		} else if _, err := tx.Exec(ctx, `UPDATE carrier_accounts SET name = coalesce(trim($3), name), config = $4, is_active = coalesce($5, is_active),
			is_default = coalesce($6, is_default) WHERE id = $1 AND company_id = $2`, id, cid, in.Name, cb, in.IsActive, in.IsDefault); err != nil {
			return nil, err
		}
		return map[string]any{"id": id}, nil
	})
}

func boolStr(b *bool) *string {
	if b == nil {
		return nil
	}
	v := strconv.FormatBool(*b)
	return &v
}

type shipmentIn struct {
	AccountID    string `json:"account_id"`
	SalesOrderID string `json:"sales_order_id"`
	ShopOrderID  string `json:"shop_order_id"`
	TripStopID   string `json:"trip_stop_id"`
	Recipient    string `json:"recipient"`
	Phone        string `json:"phone"`
	Address      string `json:"address"`
	City         string `json:"city"`
	Country      string `json:"country"`
	WeightKg     string `json:"weight_kg"`
	Pieces       int    `json:"pieces"`
	Contents     string `json:"contents"`
	Currency     string `json:"currency"`
	COD          string `json:"cod_amount"`
	Service      string `json:"service"`
	Rate         string `json:"rate"`
}

func (in *shipmentIn) normalize() bool {
	in.Recipient, in.Phone, in.Address, in.City = strings.TrimSpace(in.Recipient), strings.TrimSpace(in.Phone), strings.TrimSpace(in.Address), strings.TrimSpace(in.City)
	in.Country = strings.ToUpper(strings.TrimSpace(in.Country))
	if in.Country == "" {
		in.Country = "LB"
	}
	if in.WeightKg == "" {
		in.WeightKg = "1"
	}
	if in.Pieces == 0 {
		in.Pieces = 1
	}
	if in.COD == "" {
		in.COD = "0"
	}
	w, ok1 := money(in.WeightKg)
	c, ok2 := money(in.COD)
	return isUUID(in.AccountID) && ok1 && w.IsPositive() && w.LessThanOrEqual(decimal.NewFromInt(10000)) && ok2 && !c.IsNegative() &&
		in.Pieces >= 1 && in.Pieces <= 999 && len(in.Country) == 2 && len(in.Recipient) <= 120 && len(in.Phone) <= 40 && len(in.Address) <= 500 &&
		len(in.City) <= 80 && len(in.Contents) <= 200 && len(in.Service) <= 40 && currencyRe.MatchString(in.Currency) &&
		(in.SalesOrderID == "" || isUUID(in.SalesOrderID)) && (in.ShopOrderID == "" || isUUID(in.ShopOrderID)) && (in.TripStopID == "" || isUUID(in.TripStopID))
}

func (in *shipmentIn) req(company string, number int64) shipReq {
	w, _ := money(in.WeightKg)
	c, _ := money(in.COD)
	return shipReq{Number: number, Recipient: in.Recipient, Phone: in.Phone, Address: in.Address, City: in.City, Country: in.Country, WeightKg: w,
		Pieces: in.Pieces, Contents: in.Contents, Currency: in.Currency, COD: c, Service: in.Service, Company: company}
}

func companyLabelName(ctx context.Context, tx pgx.Tx, cid string) string {
	var n string
	_ = tx.QueryRow(ctx, `SELECT coalesce(nullif(name_en, ''), name_ar) FROM companies WHERE id = $1`, cid).Scan(&n)
	return n
}

// POST /ship/quote {account_id?, recipient fields…}: rates of one account, or of every configured active account.
func (s *Server) shipQuote(w http.ResponseWriter, r *http.Request) {
	var in shipmentIn
	if !decodeBody(w, r, &in) {
		return
	}
	all := in.AccountID == ""
	if all {
		in.AccountID = "00000000-0000-0000-0000-000000000000"
	}
	if in.Currency == "" {
		in.Currency = "USD"
	}
	if !in.normalize() {
		writeErr(w, http.StatusBadRequest, "bad_request")
		return
	}
	cid := r.PathValue("cid")
	s.run(w, r, http.StatusOK, func(ctx context.Context, tx pgx.Tx) (any, error) {
		ids := []string{in.AccountID}
		if all {
			rows, err := tx.Query(ctx, `SELECT id::text FROM carrier_accounts WHERE company_id = $1 AND is_active ORDER BY is_default DESC, name`, cid)
			if err != nil {
				return nil, err
			}
			if ids, err = pgx.CollectRows(rows, pgx.RowTo[string]); err != nil {
				return nil, err
			}
		}
		company := companyLabelName(ctx, tx, cid)
		out := []rateOption{}
		errs := []map[string]string{}
		for _, id := range ids {
			kind, name, cfg, err := carrierRow(ctx, tx, cid, id)
			if err != nil {
				return nil, err
			}
			if !carrierConfigured(kind, cfg) {
				errs = append(errs, map[string]string{"account_id": id, "name": name, "error": "carrier_not_configured"})
				continue
			}
			opts, err := carrierFor(kind).Quote(ctx, cfg, in.req(company, 0))
			if err != nil {
				var ae *apiError
				if !errors.As(err, &ae) {
					return nil, err
				}
				errs = append(errs, map[string]string{"account_id": id, "name": name, "error": ae.code, "detail": ae.detail})
				continue
			}
			for _, o := range opts {
				o.Carrier, o.Account = kind, id
				if o.Name == "" {
					o.Name = name
				} else {
					o.Name = name + " · " + o.Name
				}
				out = append(out, o)
			}
		}
		return map[string]any{"rates": out, "errors": errs}, nil
	})
}

const shipmentCols = `sh.id, sh.number, sh.account_id, ca.name AS account, sh.carrier, sh.sales_order_id, so.order_number, so.number AS quote_number,
	sh.shop_order_id, o.number AS shop_order_number, sh.trip_stop_id, sh.customer_id, sh.recipient, sh.phone, sh.address, sh.city, sh.country,
	sh.weight_kg::text AS weight_kg, sh.pieces, sh.contents, sh.currency, sh.cod_amount::text AS cod_amount, sh.rate::text AS rate, sh.service,
	sh.tracking_no, sh.label_id, sh.status, sh.events, sh.error, sh.checked_at, sh.created_at, sh.updated_at`
const shipmentFrom = ` FROM shipments sh JOIN carrier_accounts ca ON ca.id = sh.account_id LEFT JOIN sales_orders so ON so.id = sh.sales_order_id
	LEFT JOIN shop_orders o ON o.id = sh.shop_order_id`

func (s *Server) listShipments(w http.ResponseWriter, r *http.Request) {
	st := r.URL.Query().Get("status")
	if st == "" {
		st = "all"
	}
	if !contains([]string{"all", "open", "draft", "created", "in_transit", "delivered", "exception", "cancelled"}, st) {
		writeErr(w, http.StatusBadRequest, "bad_request")
		return
	}
	s.run(w, r, http.StatusOK, func(ctx context.Context, tx pgx.Tx) (any, error) {
		return queryJSON(ctx, tx, `SELECT `+shipmentCols+shipmentFrom+` WHERE sh.company_id = $1
			AND ($2 = 'all' OR sh.status = $2 OR ($2 = 'open' AND sh.status IN ('draft', 'created', 'in_transit', 'exception')))
			ORDER BY sh.created_at DESC LIMIT 500`, r.PathValue("cid"), st)
	})
}

func (s *Server) getShipment(w http.ResponseWriter, r *http.Request) {
	cid, id := r.PathValue("cid"), r.PathValue("id")
	if !isUUID(id) {
		writeErr(w, http.StatusNotFound, "not_found")
		return
	}
	s.run(w, r, http.StatusOK, func(ctx context.Context, tx pgx.Tx) (any, error) {
		return queryJSONOne(ctx, tx, `SELECT `+shipmentCols+shipmentFrom+` WHERE sh.id = $1 AND sh.company_id = $2`, id, cid)
	})
}

// GET /ship/prefill?shop_order_id=|sales_order_id=|trip_stop_id=: the recipient and the cash to collect of a document.
func (s *Server) shipPrefill(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	shop, so, stop := q.Get("shop_order_id"), q.Get("sales_order_id"), q.Get("trip_stop_id")
	cid := r.PathValue("cid")
	s.run(w, r, http.StatusOK, func(ctx context.Context, tx pgx.Tx) (any, error) {
		switch {
		case isUUID(shop):
			return queryJSONOne(ctx, tx, `SELECT o.id AS shop_order_id, o.sales_order_id, o.customer_id, o.name AS recipient, o.phone, o.address,
				coalesce(z.name, '') AS city, o.currency, CASE WHEN o.payment = 'cod' THEN so.total ELSE 0 END::text AS cod_amount
				FROM shop_orders o JOIN sales_orders so ON so.id = o.sales_order_id LEFT JOIN shop_zones z ON z.id = o.zone_id
				WHERE o.id = $1 AND o.company_id = $2`, shop, cid)
		case isUUID(so):
			return queryJSONOne(ctx, tx, `SELECT so.id AS sales_order_id, so.customer_id, c.name AS recipient, c.phone, c.address, '' AS city, so.currency,
				greatest(so.total - coalesce((SELECT sum(i.paid) FROM invoices i WHERE i.sales_order_id = so.id AND i.status <> 'void'), 0), 0)::text AS cod_amount
				FROM sales_orders so JOIN customers c ON c.id = so.customer_id WHERE so.id = $1 AND so.company_id = $2`, so, cid)
		case isUUID(stop):
			return queryJSONOne(ctx, tx, `SELECT ts.id AS trip_stop_id, ts.sales_order_id, ts.customer_id, coalesce(c.name, '') AS recipient, ts.phone, ts.address,
				'' AS city, coalesce(so.currency, (SELECT base_currency FROM companies WHERE id = ts.company_id)) AS currency, '0' AS cod_amount
				FROM trip_stops ts LEFT JOIN customers c ON c.id = ts.customer_id LEFT JOIN sales_orders so ON so.id = ts.sales_order_id
				WHERE ts.id = $1 AND ts.company_id = $2`, stop, cid)
		}
		return nil, badRequest("bad_request")
	})
}

// POST /ship/shipments {account_id, shop_order_id | sales_order_id | trip_stop_id, recipient…, book}: a shipment
// (draft; book=true also books it with the carrier at once).
func (s *Server) createShipment(w http.ResponseWriter, r *http.Request) {
	var in struct {
		shipmentIn
		Book bool `json:"book"`
	}
	if !decodeBody(w, r, &in) {
		return
	}
	if !in.normalize() || in.Recipient == "" {
		writeErr(w, http.StatusBadRequest, "bad_request")
		return
	}
	var rate *string
	if in.Rate != "" {
		v, ok := money(in.Rate)
		if !ok || v.IsNegative() {
			writeErr(w, http.StatusBadRequest, "invalid_amount")
			return
		}
		rs := v.String()
		rate = &rs
	}
	cid := r.PathValue("cid")
	s.run(w, r, http.StatusCreated, func(ctx context.Context, tx pgx.Tx) (any, error) {
		kind, _, _, err := carrierRow(ctx, tx, cid, in.AccountID)
		if err != nil {
			return nil, err
		}
		var customer *string
		for _, ref := range []struct{ q, id string }{
			{`SELECT customer_id::text FROM sales_orders WHERE id = $1 AND company_id = $2`, in.SalesOrderID},
			{`SELECT customer_id::text FROM shop_orders WHERE id = $1 AND company_id = $2`, in.ShopOrderID},
			{`SELECT customer_id::text FROM trip_stops WHERE id = $1 AND company_id = $2`, in.TripStopID},
		} {
			if ref.id == "" {
				continue
			}
			var c *string
			if err := tx.QueryRow(ctx, ref.q, ref.id, cid).Scan(&c); err != nil {
				if errors.Is(err, pgx.ErrNoRows) {
					return nil, notFound()
				}
				return nil, err
			}
			if customer == nil {
				customer = c
			}
		}
		if in.ShopOrderID != "" && in.SalesOrderID == "" {
			_ = tx.QueryRow(ctx, `SELECT sales_order_id::text FROM shop_orders WHERE id = $1`, in.ShopOrderID).Scan(&in.SalesOrderID)
		}
		if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtext('shipments:' || $1))`, cid); err != nil {
			return nil, err
		}
		var id string
		if err := tx.QueryRow(ctx, `INSERT INTO shipments (company_id, number, account_id, carrier, sales_order_id, shop_order_id, trip_stop_id, customer_id,
			recipient, phone, address, city, country, weight_kg, pieces, contents, currency, cod_amount, rate, service)
			VALUES ($1, (SELECT coalesce(max(number), 0) + 1 FROM shipments WHERE company_id = $1), $2, $3, nullif($4, '')::uuid, nullif($5, '')::uuid,
			nullif($6, '')::uuid, $7::uuid, $8, $9, $10, $11, $12, $13::numeric, $14, $15, $16, $17::numeric, $18::numeric, $19) RETURNING id::text`,
			cid, in.AccountID, kind, in.SalesOrderID, in.ShopOrderID, in.TripStopID, customer, in.Recipient, in.Phone, in.Address, in.City, in.Country,
			in.WeightKg, in.Pieces, strings.TrimSpace(in.Contents), in.Currency, in.COD, rate, in.Service).Scan(&id); err != nil {
			return nil, err
		}
		if in.Book {
			if err := bookShipment(ctx, tx, cid, id); err != nil {
				return nil, err
			}
		}
		return queryJSONOne(ctx, tx, `SELECT `+shipmentCols+shipmentFrom+` WHERE sh.id = $1`, id)
	})
}

// bookShipment asks the carrier for the tracking number and the label (kept as a file of the shipment).
func bookShipment(ctx context.Context, tx pgx.Tx, cid, id string) error {
	var status, account string
	var number int64
	var in shipmentIn
	err := tx.QueryRow(ctx, `SELECT status, number, account_id::text, recipient, phone, address, city, country, weight_kg::text, pieces, contents, currency,
		cod_amount::text, service FROM shipments WHERE id = $1 AND company_id = $2 FOR UPDATE`, id, cid).Scan(&status, &number, &account, &in.Recipient, &in.Phone,
		&in.Address, &in.City, &in.Country, &in.WeightKg, &in.Pieces, &in.Contents, &in.Currency, &in.COD, &in.Service)
	if errors.Is(err, pgx.ErrNoRows) {
		return notFound()
	}
	if err != nil {
		return err
	}
	if status != "draft" {
		return &apiError{status: http.StatusConflict, code: "wrong_status"}
	}
	kind, _, cfg, err := carrierRow(ctx, tx, cid, account)
	if err != nil {
		return err
	}
	if !carrierConfigured(kind, cfg) {
		return &apiError{status: http.StatusUnprocessableEntity, code: "carrier_not_configured"}
	}
	company := companyLabelName(ctx, tx, cid)
	tracking, label, err := carrierFor(kind).Create(ctx, cfg, in.req(company, number))
	if err != nil {
		var ae *apiError
		if errors.As(err, &ae) {
			_, _ = tx.Exec(ctx, `UPDATE shipments SET error = left($2, 500), updated_at = now() WHERE id = $1`, id, ae.detail)
		}
		return err
	}
	if len(label) == 0 { // the carrier sent no label: our own one, with its tracking number
		label = shippingLabel(cfg, in.req(company, number), tracking, strings.ToUpper(kind))
	}
	var lid string
	if err := tx.QueryRow(ctx, `INSERT INTO attachments (company_id, entity_type, entity_id, filename, mime, size, data, note)
		VALUES ($1, 'shipment', $2, $3, 'application/pdf', $4, $5, 'label') RETURNING id::text`, cid, id, fmt.Sprintf("label-%s.pdf", tracking), len(label), label).Scan(&lid); err != nil {
		return err
	}
	ev, _ := json.Marshal([]shipEvent{{At: time.Now().Format(time.RFC3339), Status: "created", Text: "Label created"}})
	_, err = tx.Exec(ctx, `UPDATE shipments SET status = 'created', tracking_no = $2, label_id = $3, events = $4, error = '', updated_at = now() WHERE id = $1`,
		id, tracking, lid, ev)
	return err
}

// POST /ship/shipments/{id}/{action}: book | track | cancel | status {status, note}
func (s *Server) shipmentAction(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Status string `json:"status"`
		Note   string `json:"note"`
	}
	if !decodeBody(w, r, &in) {
		return
	}
	cid, id, action := r.PathValue("cid"), r.PathValue("id"), r.PathValue("action")
	if !isUUID(id) || !contains([]string{"book", "track", "cancel", "status"}, action) || len(in.Note) > 200 {
		writeErr(w, http.StatusNotFound, "not_found")
		return
	}
	s.run(w, r, http.StatusOK, func(ctx context.Context, tx pgx.Tx) (any, error) {
		switch action {
		case "book":
			if err := bookShipment(ctx, tx, cid, id); err != nil {
				return nil, err
			}
		case "track":
			if err := trackShipment(ctx, tx, cid, id); err != nil {
				return nil, err
			}
		case "cancel", "status":
			var status string
			if err := tx.QueryRow(ctx, `SELECT status FROM shipments WHERE id = $1 AND company_id = $2 FOR UPDATE`, id, cid).Scan(&status); err != nil {
				if errors.Is(err, pgx.ErrNoRows) {
					return nil, notFound()
				}
				return nil, err
			}
			next := "cancelled"
			if action == "status" {
				next = in.Status
				if !contains([]string{"in_transit", "delivered", "exception"}, next) || status == "draft" {
					return nil, badRequest("bad_status")
				}
			}
			if status == "cancelled" || status == "delivered" {
				return nil, &apiError{status: http.StatusConflict, code: "wrong_status"}
			}
			ev, _ := json.Marshal([]shipEvent{{At: time.Now().Format(time.RFC3339), Status: next, Text: strings.TrimSpace(in.Note)}})
			if _, err := tx.Exec(ctx, `UPDATE shipments SET status = $2, events = events || $3::jsonb, updated_at = now() WHERE id = $1`, id, next, ev); err != nil {
				return nil, err
			}
		}
		return queryJSONOne(ctx, tx, `SELECT `+shipmentCols+shipmentFrom+` WHERE sh.id = $1`, id)
	})
}

func trackShipment(ctx context.Context, tx pgx.Tx, cid, id string) error {
	var account, tracking, status string
	err := tx.QueryRow(ctx, `SELECT account_id::text, tracking_no, status FROM shipments WHERE id = $1 AND company_id = $2 FOR UPDATE`, id, cid).Scan(&account, &tracking, &status)
	if errors.Is(err, pgx.ErrNoRows) {
		return notFound()
	}
	if err != nil {
		return err
	}
	if tracking == "" || status == "cancelled" {
		return &apiError{status: http.StatusConflict, code: "wrong_status"}
	}
	kind, _, cfg, err := carrierRow(ctx, tx, cid, account)
	if err != nil {
		return err
	}
	st, ev, err := carrierFor(kind).Track(ctx, cfg, tracking)
	if err != nil {
		return err
	}
	if st == "" { // manual: nothing to ask
		_, err = tx.Exec(ctx, `UPDATE shipments SET checked_at = now() WHERE id = $1`, id)
		return err
	}
	if status == "delivered" {
		st = "delivered"
	}
	eb, _ := json.Marshal(ev)
	_, err = tx.Exec(ctx, `UPDATE shipments SET status = $2, events = $3, checked_at = now(), updated_at = now() WHERE id = $1`, id, st, eb)
	return err
}

// StartShipWorker refreshes the tracking of open carrier shipments every 30 minutes.
func (s *Server) StartShipWorker(ctx context.Context) {
	if s.OwnerPool == nil {
		return
	}
	go func() {
		t := time.NewTicker(30 * time.Minute)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				s.RunShipTracking(ctx)
			}
		}
	}()
}

func (s *Server) RunShipTracking(ctx context.Context) {
	rows, err := s.OwnerPool.Query(ctx, `SELECT tenant_id::text, company_id::text, id::text FROM shipments
		WHERE status IN ('created', 'in_transit') AND carrier <> 'manual' AND tracking_no <> '' AND (checked_at IS NULL OR checked_at < now() - interval '25 minutes')
		AND tenant_jobs_ok(tenant_id) ORDER BY checked_at NULLS FIRST LIMIT 200`)
	if err != nil {
		slog.Error("ship tracking", "err", err)
		return
	}
	type row struct{ t, c, id string }
	list, err := pgx.CollectRows(rows, func(r pgx.CollectableRow) (row, error) {
		var x row
		err := r.Scan(&x.t, &x.c, &x.id)
		return x, err
	})
	if err != nil {
		return
	}
	for _, x := range list {
		err := s.inJobTx(ctx, x.t, func(tx pgx.Tx) error {
			err := trackShipment(ctx, tx, x.c, x.id)
			var ae *apiError
			if errors.As(err, &ae) { // the carrier refused: try again next round
				_, err = tx.Exec(ctx, `UPDATE shipments SET checked_at = now(), error = left($2, 500) WHERE id = $1`, x.id, ae.code+" "+ae.detail)
			}
			return err
		})
		if err != nil {
			slog.Error("ship tracking", "shipment", x.id, "err", err)
		}
	}
}
